fn all_characters_same(char_arr: &Vec<char>) -> bool {
    // If the array is empty or has just one element, it trivially satisfies the condition.
    if let Some(&first) = char_arr.first() {
        // Check that every character in the vector equals the first one.
        char_arr.iter().all(|&c| c == first)
    } else {
        true
    }
}

